‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍
 */

class SystemLogController
{
    private static bool $tableEnsured = false;

    public function index(): void
    {
        try {
            if (session_status() === PHP_SESSION_ACTIVE) {
                session_write_close();
            }
            $db = Database::getConnection();

            // Ensure table exists
            if (!self::$tableEnsured) {
                $db->exec("CREATE TABLE IF NOT EXISTS system_logs (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    user_id INT NULL,
                    username VARCHAR(255) NULL,
                    module VARCHAR(50) NOT NULL,
                    action VARCHAR(50) NOT NULL,
                    entity_id INT NULL,
                    entity_name VARCHAR(255) NULL,
                    details TEXT NULL,
                    ip_address VARCHAR(45) NULL,
                    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    INDEX idx_module (module),
                    INDEX idx_action (action),
                    INDEX idx_user_id (user_id),
                    INDEX idx_created_at (created_at),
                    INDEX idx_user_action_created (user_id, action, created_at),
                    INDEX idx_module_created (module, created_at),
                    INDEX idx_module_entity (module, entity_id),
                    INDEX idx_entity_id (entity_id),
                    INDEX idx_action_created (action, created_at),
                    INDEX idx_ip_created (ip_address, created_at)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
                self::$tableEnsured = true;
            }

            $page        = max(1, (int) ($_GET['page'] ?? 1));
            $isPrintMode = !empty($_GET['is_print']) || ((int)($_GET['per_page'] ?? 0) > 100);
            $maxAllowed  = $isPrintMode ? 5000 : 100;
            $perPage     = min($maxAllowed, max(10, (int) ($_GET['per_page'] ?? 50)));
            $module   = trim($_GET['module'] ?? '');
            $action   = trim($_GET['action'] ?? '');
            $userId   = trim($_GET['user_id'] ?? '');
            $search   = trim($_GET['search'] ?? '');
            $entityId = trim($_GET['entity_id'] ?? '');
            $dateFrom = trim($_GET['date_from'] ?? '');
            $dateTo   = trim($_GET['date_to'] ?? '');

            $where  = [];
            $params = [];

            if ($module !== '') {
                if (strpos($module, ',') !== false) {
                    $modList = array_filter(array_map('trim', explode(',', $module)));
                    if (!empty($modList)) {
                        $placeholders = [];
                        foreach ($modList as $idx => $modVal) {
                            $pKey = 'module_' . $idx;
                            $placeholders[] = ':' . $pKey;
                            $params[$pKey] = $modVal;
                        }
                        $where[] = 'module IN (' . implode(',', $placeholders) . ')';
                    }
                } else {
                    $where[]          = 'module = :module';
                    $params['module'] = $module;
                }
            }
            if ($action !== '') {
                $where[]          = 'action = :action';
                $params['action'] = $action;
            }
            if ($userId !== '') {
                $where[]           = 'user_id = :user_id';
                $params['user_id'] = $userId;
            }
            if ($search !== '') {
                $where[]          = '(entity_name LIKE :search OR details LIKE :search2 OR username LIKE :search3 OR ip_address LIKE :search4)';
                $params['search']  = '%' . $search . '%';
                $params['search2'] = '%' . $search . '%';
                $params['search3'] = '%' . $search . '%';
                $params['search4'] = '%' . $search . '%';
            }
            if ($entityId !== '') {
                $where[] = '(entity_id = :entity_id OR details LIKE :entity_id_search)';
                $params['entity_id']        = (int)$entityId;
                $params['entity_id_search'] = '%"bill_id":' . (int)$entityId . '%';
            }
            if ($dateFrom !== '') {
                $where[]              = 'created_at >= :date_from';
                $params['date_from']  = $dateFrom . ' 00:00:00';
            }
            if ($dateTo !== '') {
                $where[]            = 'created_at <= :date_to';
                $params['date_to']  = $dateTo . ' 23:59:59';
            }

            $whereClause = count($where) > 0 ? 'WHERE ' . implode(' AND ', $where) : '';

            // Total count
            $countSql = "SELECT COUNT(*) as total FROM system_logs $whereClause";
            $countStmt = $db->prepare($countSql);
            $countStmt->execute($params);
            $total = (int) $countStmt->fetch()['total'];

            // Paginated results (deterministic ordering with tie-breaker id DESC)
            $offset = ($page - 1) * $perPage;
            $sql = "SELECT * FROM system_logs $whereClause ORDER BY created_at DESC, id DESC LIMIT $perPage OFFSET $offset";
