    public function recordPrint(array $data): void
    {
        try {
            $allowedTypes = [
                'client_ticket' => 'Client Ticket',
                'user_report'   => 'User Report (A4)',
                'quick_ticket'  => 'Quick Client Ticket',
            ];

            $type = isset($data['print_type']) ? trim((string) $data['print_type']) : '';
            if (!isset($allowedTypes[$type])) {
                Response::json(['error' => 'Invalid print_type'], 400);
                return;
            }

            $orderId   = isset($data['order_id']) && $data['order_id'] !== '' ? (int) $data['order_id'] : null;
            $orderUid  = isset($data['order_uid']) ? trim((string) $data['order_uid']) : '';
            $customer  = isset($data['customer_name']) ? trim((string) $data['customer_name']) : '';
            $madeBy    = isset($data['made_by']) ? trim((string) $data['made_by']) : '';
            $selected  = isset($data['selected']) ? trim((string) $data['selected']) : '';

            $entityName = $orderUid !== '' ? $orderUid : ($orderId ? ('Order #' . $orderId) : 'Order');

            $printedBy = null;
            $actorId = $_SESSION['user_id'] ?? null;
            if ($actorId) {
                $stmt = Database::getConnection()->prepare('SELECT username FROM users WHERE id = :id LIMIT 1');
                $stmt->execute(['id' => $actorId]);
                $row = $stmt->fetch();
                $printedBy = $row ? $row['username'] : null;
            }

            $selectedKey = $type === 'user_report'
                ? 'Selected data to include on the A4 page'
                : 'Selected data to include on the ticket';

            $detailParts = [
                'made_by'    => $madeBy !== '' ? $madeBy : '—',
                'printed_by' => $printedBy ?: '—',
                'type'       => $allowedTypes[$type],
                'order'      => $entityName,
                'customer'   => $customer !== '' ? $customer : '—',
            ];
            if ($type !== 'quick_ticket') {
                $detailParts[$selectedKey] = $selected !== '' ? $selected : '—';
            }

            SystemLog::write(
                'prints',
                'printed_' . $type,
                $orderId,
                $entityName,
                json_encode($detailParts, JSON_UNESCAPED_UNICODE)
            );

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[SYSTEM LOG PRINT ERROR] ' . $e->getMessage());
            Response::json(['error' => 'Failed to record print activity. Please check server error logs.'], 500);
        }
    }

    public function recordSyslogPrint(array $data): void
    {
        try {
            $entriesPrinted = isset($data['entries_printed']) ? (int) $data['entries_printed'] : 0;
