            $filters        = isset($data['filters']) && is_array($data['filters']) ? $data['filters'] : [];
            $columns        = isset($data['columns']) && is_array($data['columns']) ? $data['columns'] : [];

            $printedBy = null;
            $actorId = $_SESSION['user_id'] ?? null;
            if ($actorId) {
                $stmt = Database::getConnection()->prepare('SELECT username FROM users WHERE id = :id LIMIT 1');
                $stmt->execute(['id' => $actorId]);
                $row = $stmt->fetch();
                $printedBy = $row ? $row['username'] : null;
            }

            $activeFilters = [];
            foreach (['module', 'action', 'user_id', 'date_from', 'date_to', 'search'] as $key) {
                if (isset($filters[$key]) && $filters[$key] !== '' && $filters[$key] !== null) {
                    $activeFilters[$key] = $filters[$key];
                }
            }

            $detailParts = [
                'printed_by'      => $printedBy ?: '—',
                'type'            => 'System Activity Logs (A4 PDF)',
                'entries_printed' => $entriesPrinted,
